create type public.user_role as enum ('super_admin','dealer','customer');
create type public.dealer_status as enum ('pending','approved','suspended');
create type public.car_type as enum ('economy','family','suv','luxury','minibus');
create type public.car_status as enum ('available','rented','maintenance');
create type public.booking_status as enum ('pending','confirmed','rejected','cancelled');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role public.user_role not null default 'customer', full_name text, phone text, created_at timestamptz not null default now());
create table public.dealers (id uuid primary key default gen_random_uuid(), user_id uuid unique not null references auth.users(id) on delete cascade, name text not null, city text not null, phone text not null, address text not null, status public.dealer_status not null default 'pending', created_at timestamptz not null default now());
create table public.cars (id uuid primary key default gen_random_uuid(), dealer_id uuid not null references public.dealers(id) on delete cascade, name text not null, type public.car_type not null, price_per_day numeric(12,2) not null check(price_per_day>=0), extra_per_km numeric(12,2) not null default 0 check(extra_per_km>=0), status public.car_status not null default 'available', photo_url text, created_at timestamptz not null default now());
create table public.bookings (id uuid primary key default gen_random_uuid(), customer_id uuid not null references auth.users(id), dealer_id uuid not null references public.dealers(id), car_id uuid not null references public.cars(id), origin_city text not null, destination_city text not null, distance_km numeric(10,2) not null check(distance_km>=0), start_date date not null, days integer not null check(days>0), price_per_day numeric(12,2) not null, extra_per_km numeric(12,2) not null, total_price numeric(12,2) not null, status public.booking_status not null default 'pending', terms_accepted_at timestamptz not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index bookings_dealer_idx on public.bookings(dealer_id); create index bookings_customer_idx on public.bookings(customer_id); create index cars_dealer_idx on public.cars(dealer_id);
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=(select auth.uid()) and role='super_admin') $$;
revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to authenticated;
create function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$; create trigger bookings_updated before update on public.bookings for each row execute procedure public.set_updated_at();
alter table public.profiles enable row level security; alter table public.dealers enable row level security; alter table public.cars enable row level security; alter table public.bookings enable row level security;
create policy "profiles own or admin" on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_admin()); create policy "profiles update own" on public.profiles for update to authenticated using(id=(select auth.uid()) or public.is_admin()) with check(id=(select auth.uid()) or public.is_admin());
create policy "approved dealers are public" on public.dealers for select to authenticated using(status='approved' or user_id=(select auth.uid()) or public.is_admin()); create policy "admins manage dealers" on public.dealers for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "dealer creates self" on public.dealers for insert to authenticated with check(user_id=(select auth.uid()) and status='pending'); create policy "dealer updates self" on public.dealers for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and status='pending');
create policy "available approved cars public" on public.cars for select to authenticated using(exists(select 1 from public.dealers d where d.id=dealer_id and (d.status='approved' or d.user_id=(select auth.uid()) or public.is_admin()))); create policy "dealer manages cars" on public.cars for all to authenticated using(exists(select 1 from public.dealers d where d.id=dealer_id and d.user_id=(select auth.uid())) or public.is_admin()) with check(exists(select 1 from public.dealers d where d.id=dealer_id and d.user_id=(select auth.uid())) or public.is_admin());
create policy "booking parties or admin select" on public.bookings for select to authenticated using(customer_id=(select auth.uid()) or exists(select 1 from public.dealers d where d.id=dealer_id and d.user_id=(select auth.uid())) or public.is_admin()); create policy "customer creates booking" on public.bookings for insert to authenticated with check(customer_id=(select auth.uid()) and exists(select 1 from public.cars c join public.dealers d on d.id=c.dealer_id where c.id=car_id and c.dealer_id=dealer_id and d.status='approved' and c.status='available'));
create policy "customer cancels own booking" on public.bookings for update to authenticated using(customer_id=(select auth.uid())) with check(customer_id=(select auth.uid()) and status='cancelled'); create policy "dealer responds own booking" on public.bookings for update to authenticated using(exists(select 1 from public.dealers d where d.id=dealer_id and d.user_id=(select auth.uid()))) with check(exists(select 1 from public.dealers d where d.id=dealer_id and d.user_id=(select auth.uid())));
insert into storage.buckets(id,name,public) values ('car-photos','car-photos',true); create policy "dealer uploads own photos" on storage.objects for insert to authenticated with check(bucket_id='car-photos' and (storage.foldername(name))[1]=(select auth.uid())::text); create policy "public reads car photos" on storage.objects for select using(bucket_id='car-photos'); create policy "dealer updates own photos" on storage.objects for update to authenticated using(bucket_id='car-photos' and owner_id=(select auth.uid())) with check(bucket_id='car-photos' and owner_id=(select auth.uid()));
alter publication supabase_realtime add table public.bookings;
